-- public.perform_sacrifice(p_world uuid, p_uid uuid, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.perform_sacrifice(p_world uuid, p_uid uuid, p_target jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare s record; v_name text;
begin
  select * into s from sacrifice_setting(p_world, p_uid, p_target);
  if s.o_why is not null then return; end if;
  v_name := lower(item_name(s.o_item));
  perform consume(p_world, p_uid, (s.o_item).def, 1, (s.o_item).id);
  perform journal_note(p_world, p_uid, 'sacrificed');
  update player set nutrition = coalesce(nutrition, '{}'::jsonb)
                                || (select jsonb_object_agg(k, 1) from unnest(nutrients()) k)
   where world_id = p_world and uid = p_uid;
  perform tell(p_world, p_uid, 'Sacrificed: ' || v_name || '. ' || fed_said(), 'event');
  if random() < soul_chance() then
    perform give(p_world, p_uid, 'soul', 1, (s.o_item).ql, null, (s.o_item).rare);
    perform tell(p_world, p_uid, 'Got: ' || (s.o_item).rare || ' soul.', 'event');
  end if;
  -- And soul strength, as every one of its sources teaches it (`SOUL_GAIN`).
  perform skill_told(p_world, p_uid, 'soul_strength', try_gain(true, soul_gain()));
end $function$
